#!/usr/bin/env bash
# Regenerates the argument reference from pidsmaker/config/config.py, then builds the site.
# Run from the pids container (the argument reference is generated by importing pidsmaker).
set -e
cd "$(dirname "$0")"

python scripts/get_arguments.py        # docs/scripts/args/*.md

if ! command -v zensical >/dev/null 2>&1; then
  echo "zensical not found. It needs Python >= 3.10: in the pids container, install it in the base conda env with:"
  echo "  /opt/conda/bin/pip install zensical"
  exit 1
fi
zensical build --clean
